import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {resolve} from 'node:path';
import {withRuntime} from '../../../packages/workshop-tools/policy/runtime.ts';
import {sha256} from '../../../packages/workshop-tools/runtime-bundle.ts';
import {compareScores,scoreVector} from '../../../src/shared/policy/scoring.ts';
const out='test-results/emberwake-strength/performance-rescore-1';
await mkdir(out,{recursive:true});
await withRuntime({game:'emberwake',retain:out+'/bundles'},async(runtime,provenance)=>{
 const originalDirectory='test-results/emberwake-strength/recorded-development-3';
 const source=JSON.parse(await readFile(originalDirectory+'/result.json','utf8'));
 const rows=[];
 for(const artifact of source.artifacts){
  const bytes=await readFile(artifact.path),digest=sha256(bytes);
  if(digest!==artifact.sha256)throw new Error('Original rollout bytes changed: '+artifact.path);
  const run=runtime.parseRollout(bytes.toString());
  if(run.replay.commands.some(c=>c.type==='respawn'||c.type.startsWith('dev-')))throw new Error('Outside first-death campaign');
  const native=runtime.adapter.restore(run.replay),metrics=runtime.adapter.metrics(native);
  for(const [name,value]of Object.entries(run.episode.metrics))if(JSON.stringify(metrics[name])!==JSON.stringify(value))throw new Error('Historical metric changed: '+name);
  const definition=runtime.study.score;
  scoreVector(definition,metrics.score);
  const hero=run.options.setup.hero,journalText=JSON.stringify(run.replay)+'\n',journalPath=out+'/'+hero+'-standard.native-replay.json';
  await writeFile(journalPath,journalText,{flag:'wx'});
  const sidecar={schema:'emberwake-evaluator-score-2',scope:'Evaluator reconstruction and rescoring of a retained native command journal. Not a fresh policy rollout; original inputs and score1 artifact unchanged.',original:{path:artifact.path,sha256:digest,digest:run.digest,identity:run.identity,metrics:run.episode.metrics,provenance:run.provenance},identity:runtime.adapter.identity,scoreDefinition:definition,metrics,provenance,journal:{path:journalPath,sha256:sha256(journalText),extraction:'New canonical JSON serialization of the unchanged replay value in the original rollout.'},checks:{originalArtifactBytes:'unchanged',nativeReplay:'reconstructed',historicalMetrics:'unchanged',score:'derived under new identity',freshPolicyExecution:false,originalInputsRegenerated:false}};
  const path=out+'/'+hero+'-standard.score.json';await writeFile(path,JSON.stringify(sidecar,null,2)+'\n',{flag:'wx'});
  rows.push({hero,path,sha256:sha256(await readFile(path)),score:metrics.score,originalSha256:digest,journalSha256:sidecar.journal.sha256});
 }
 const diagnosticPath='test-results/emberwake-strength/development-screen-3.json',diagnosticBytes=await readFile(diagnosticPath),diagnostic=JSON.parse(diagnosticBytes.toString());
 const annotated=diagnostic.results.map(row=>({...row,score:[row.metrics.won,row.metrics.bosses,row.metrics.wards,row.metrics.regions,row.metrics.won?row.metrics.executedTicks:0]}));
 const paired=[];
 for(const hero of ['barbarian','sorceress','necromancer'])for(const difficulty of ['relaxed','standard','severe'])for(const[a,b]of[['immediate','survival'],['immediate','growth'],['survival','growth']]){
  const counts={better:0,tied:0,worse:0};
  for(const seed of [...new Set(annotated.map(row=>row.seed))]){
   const left=annotated.find(row=>row.hero===hero&&row.difficulty===difficulty&&row.strategy===a&&row.seed===seed),right=annotated.find(row=>row.hero===hero&&row.difficulty===difficulty&&row.strategy===b&&row.seed===seed);
   const comparison=compareScores(runtime.study.score,left.score,right.score);counts[comparison>0?'better':comparison<0?'worse':'tied']++;
  }
  paired.push({hero,difficulty,a,b,seedBlocks:2,...counts});
 }
 const sourceChanges=[];
 for(const[path,expected]of Object.entries({...provenance.sourceDigests,...provenance.toolDigests}))if(sha256(await readFile(path))!==expected)sourceChanges.push(path);
 const result={schema:'emberwake-score-development-2',scope:'Posthoc evaluator rescoring, not prospective validation or new reserved evidence. Three native journals reconstructed; 54 older diagnostic rows annotated from retained metrics only.',identity:runtime.adapter.identity,scoreDefinition:runtime.study.score,provenance,sidecars:rows,diagnostic:{path:diagnosticPath,sha256:sha256(diagnosticBytes),originalProvenance:diagnostic.provenance,rows:annotated,paired},sourceChanges};
 await writeFile(out+'/result.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({sidecars:rows,sourceChanges}));
});

score-assessment.source:
import {readFile,writeFile} from 'node:fs/promises';
const directory='test-results/emberwake-strength/recorded-development-3',rows=[];
for(const hero of ['barbarian','sorceress','necromancer']){
 const run=JSON.parse(await readFile(directory+'/POLICY-ADOPTION-1-DEV-01-'+hero+'-standard-survival.rollout.json','utf8'));
 const counts={},recovery={refugeHpBars:0,refugeManaBars:0};
 for(const decision of run.decisions){
  const command=decision.output.command;
  counts[command.type]=(counts[command.type]??0)+1;
  if(command.type==='potion')counts['potion:'+command.kind]=(counts['potion:'+command.kind]??0)+1;
  if(command.type==='portal'){
   recovery.refugeHpBars+=1-decision.input.player.hp/decision.input.stats.maxHp;
   recovery.refugeManaBars+=1-decision.input.player.mana/decision.input.stats.maxMana;
  }
 }
 const last=run.decisions.at(-1).input;
 rows.push({hero,episode:run.episode,lastCommand:run.decisions.at(-1).output.command,
  finalHealth:{hp:last.player.hp,maxHp:last.stats.maxHp,ratio:last.player.hp/last.stats.maxHp},
  finalMana:{mana:last.player.mana,maxMana:last.stats.maxMana,ratio:last.player.mana/last.stats.maxMana},
  finalPotions:{health:last.player.healthPotions,mana:last.player.manaPotions},counts,recovery,
  nativeCommands:run.replay.commands.length,nativeZeroTimeCommands:run.replay.commands.filter(c=>c.type!=='advance').length});
}
await writeFile('test-results/emberwake-strength/score-assessment-1.json',JSON.stringify({scope:'Read-only posthoc descriptive assessment of retained development evidence; not prospective scoring validation.',rows},null,2));
console.log(JSON.stringify(rows));
